@riverpod
class MailboxNotifier extends _$MailboxNotifier {
  late final MailboxRepository _mailboxRepository;
  int offset = 1;
  int limit = 50;
  bool isMaxMailbox = false;
  bool isFetching = false;
  List<MailboxData> mailboxList = [];

  @override
  MailboxState build() {
    _mailboxRepository = ref.watch(mailboxRepositoryProvider);
    return MailboxState(
      data: const AsyncValue.loading(),
      totalData: 0,
    );
  }

  Future<void> getMailboxList({bool isRefresh = false}) async {
    try {
      isFetching = true;
      final result = await _mailboxRepository.mailboxList(limit: limit, offset: offset);
      if ((result.dataSet ?? []).length < limit) {
        isMaxMailbox = true;
      } else {
        offset++;
      }
      if (isRefresh) mailboxList.clear();
      mailboxList.addAll(result.dataSet ?? []);
      isFetching = false;
      state = MailboxState(
        data: AsyncValue.data(mailboxList),
        totalData: result.meta?.totalData ?? 0,
      );
    } on ErrorData catch (e) {
      isFetching = false;
      state = MailboxState(
        data: AsyncValue.error(e.message ?? '', StackTrace.current),
        totalData: 0,
      );
    }
  }
}

class LoginRouteGuard extends AutoRouteGuard {
  @override
  void onNavigation(NavigationResolver resolver, StackRouter router) async {
    CacheUtil.getBoolean(Strings.keyIsLogin).then(
      (isLogin) {
        if (isLogin) {
          CacheUtil.getBoolean(Strings.keyIsNewUser).then((isNewUser) {
            if (isNewUser) {
              router.push(const RouteNewAccount());
            } else {
              CacheUtil.getBoolean(Strings.keyIsVerified).then(
                (isVerified) {
                  if (isVerified) {
                    router.push(RouteDashboard());
                  } else {
                    router.push(RouteEditProfile(isInitialPage: true));
                  }
                },
              );
            }
          });
        } else {
          resolver.next(true);
        }
      },
    );
  }
}

class RefreshTokenInterceptor extends Interceptor {
  RefreshTokenInterceptor(this.baseHttpClient, this.parentContainer);
  final BaseHttpClient baseHttpClient;
  final ProviderContainer parentContainer;

  @override
  Future<void> onResponse(
    Response<dynamic> response,
    ResponseInterceptorHandler handler,
  ) async {
    try {
      final header = response.requestOptions.headers;
      if ((response.statusCode ?? 0) >= 400 && (response.statusCode ?? 0) < 500) {
        if ((response.statusCode ?? 0) == 401) {
          final SignUpData? value = await getRefreshToken();
          if (value == null) {
            handler.resolve(response);
          } else {
            header["Authorization"] =
                "Bearer ${await CacheUtil.getString(Strings.keyAccessToken)}";
            dynamic newData = response.requestOptions.data;
            if (newData is FormData) {
              newData = await _remakeFormData(newData, response.requestOptions.extra);
            }
            final Response<dynamic> value = await baseHttpClient.client
                .fetch<dynamic>(response.requestOptions
                .copyWith(headers: header, data: newData));
            handler.resolve(value);
            return;
          }
        }
      }
      super.onResponse(response, handler);
    } catch (e) {
      return;
    }
  }
}

class CacheUtil {
  CacheUtil._();

  static Future<void> putString(String key, String value) async {
    await FlutterKeychain.put(key: key, value: value);
  }

  static Future<String> getString(String key) async {
    final value = await FlutterKeychain.get(key: key);
    return value ?? '';
  }

  static Future<bool> getBoolean(String key) async {
    final value = await FlutterKeychain.get(key: key);
    return value == 'true';
  }

  static Future<Uint8List?> getUint8List(String key) async {
    final value = await FlutterKeychain.get(key: key);
    if (value == null) return null;
    List<String> stringList = value.replaceAll('[', '').replaceAll(']', '').split(', ');
    List<int> intList = stringList.map(int.parse).toList();
    return Uint8List.fromList(intList);
  }

  static Future<void> clear() async {
    await FlutterKeychain.clear();
  }
}

